from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # employee -> year -> list of (start, end, days_used)
        self._requests: dict[str, dict[int, list[tuple[date, date, int]]]] = {}

    def _is_working_day(self, d: date) -> bool:
        # Weekends: Saturday (5) and Sunday (6)
        if d.weekday() >= 5:
            return False
        if d in self.holidays:
            return False
        return True

    def _count_leave_days(self, start: date, end: date) -> int:
        count = 0
        current = start
        while current <= end:
            if self._is_working_day(current):
                count += 1
            current += timedelta(days=1)
        return count

    def _used_days(self, employee: str, year: int) -> int:
        total = 0
        for _, _, days in self._requests.get(employee, {}).get(year, []):
            total += days
        return total

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date is before start date.")
        if (start - today).days < 3:
            raise ValueError("Leave must be requested at least 3 days in advance.")

        days_needed = self._count_leave_days(start, end)

        # Check remaining for each year touched by the request
        years = set(range(start.year, end.year + 1))
        for year in years:
            used = self._used_days(employee, year)
            remaining = self.days_per_year - used
            # Only count days in this year for the check
            year_start = max(start, date(year, 1, 1))
            year_end = min(end, date(year, 12, 31))
            needed_in_year = self._count_leave_days(year_start, year_end)
            if needed_in_year > remaining:
                raise ValueError(
                    f"Insufficient leave days remaining for {employee} in {year}."
                )

        # Record the request split by year (for accurate accounting)
        emp = self._requests.setdefault(employee, {})
        for year in years:
            year_start = max(start, date(year, 1, 1))
            year_end = min(end, date(year, 12, 31))
            days_in_year = self._count_leave_days(year_start, year_end)
            emp.setdefault(year, []).append((start, end, days_in_year))

        return days_needed

    def remaining(self, employee: str, year: int) -> int:
        used = self._used_days(employee, year)
        return max(0, self.days_per_year - used)
